import (
	"fmt"
	"os"
)

func main() {
	tasks := []string{"write tests"}
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Println("usage: todo <add|list> [task]")
		return
	}
	switch args[0] {
	case "add":
		if len(args) < 2 {
			fmt.Println("add what?")
			return
		}
		tasks = append(tasks, args[1])
		fmt.Println("added:", args[1])
	case "list":
		for i, t := range tasks {
			fmt.Println(i+1, t)
		}
	default:
		fmt.Println("unknown command:", args[0])
	}
}

